// SlackServiceServer is the server API for SlackService service.
// All implementations should embed UnimplementedSlackServiceServer
// for forward compatibility.
//
// SlackService proxies the Slack Web API (https://api.slack.com/methods).
//
// Authentication uses a bot user OAuth token (xoxb-...) supplied via the
// SLACK_BOT_TOKEN env var. All responses are returned as google.protobuf.Struct
// to preserve the upstream JSON shape (Slack response payloads are heavily
// polymorphic and evolve frequently).
type SlackServiceServer interface {
	// auth.test -- verify the configured token and return identity info.
	AuthTest(context.Context, *AuthTestRequest) (*structpb.Struct, error)
	// chat.postMessage -- send a message to a channel, DM, or thread.
	ChatPostMessage(context.Context, *ChatPostMessageRequest) (*structpb.Struct, error)
	// chat.postEphemeral -- send a message visible only to one user.
	ChatPostEphemeral(context.Context, *ChatPostEphemeralRequest) (*structpb.Struct, error)
	// chat.update -- update an existing message.
	ChatUpdate(context.Context, *ChatUpdateRequest) (*structpb.Struct, error)
	// chat.delete -- delete an existing message.
	ChatDelete(context.Context, *ChatDeleteRequest) (*structpb.Struct, error)
	// chat.scheduleMessage -- schedule a message for a future post time.
	ChatScheduleMessage(context.Context, *ChatScheduleMessageRequest) (*structpb.Struct, error)
	// chat.deleteScheduledMessage -- cancel a scheduled message.
	ChatDeleteScheduledMessage(context.Context, *ChatDeleteScheduledMessageRequest) (*structpb.Struct, error)
	// chat.getPermalink -- get a permalink URL for a posted message.
	ChatGetPermalink(context.Context, *ChatGetPermalinkRequest) (*structpb.Struct, error)
	// conversations.list -- list channels available to the bot.
	ConversationsList(context.Context, *ConversationsListRequest) (*structpb.Struct, error)
	// conversations.history -- fetch messages from a channel.
	ConversationsHistory(context.Context, *ConversationsHistoryRequest) (*structpb.Struct, error)
	// conversations.replies -- fetch replies for a thread.
	ConversationsReplies(context.Context, *ConversationsRepliesRequest) (*structpb.Struct, error)
	// conversations.info -- get metadata for a channel.
	ConversationsInfo(context.Context, *ConversationsInfoRequest) (*structpb.Struct, error)
	// conversations.create -- create a public or private channel.
	ConversationsCreate(context.Context, *ConversationsCreateRequest) (*structpb.Struct, error)
	// conversations.join -- have the bot join a channel.
	ConversationsJoin(context.Context, *ConversationsJoinRequest) (*structpb.Struct, error)
	// conversations.leave -- have the bot leave a channel.
	ConversationsLeave(context.Context, *ConversationsLeaveRequest) (*structpb.Struct, error)
	// conversations.invite -- invite users to a channel.
	ConversationsInvite(context.Context, *ConversationsInviteRequest) (*structpb.Struct, error)
	// conversations.kick -- remove a user from a channel.
	ConversationsKick(context.Context, *ConversationsKickRequest) (*structpb.Struct, error)
	// conversations.archive -- archive a channel.
	ConversationsArchive(context.Context, *ConversationsArchiveRequest) (*structpb.Struct, error)
	// conversations.unarchive -- unarchive a channel.
	ConversationsUnarchive(context.Context, *ConversationsUnarchiveRequest) (*structpb.Struct, error)
	// conversations.rename -- rename a channel.
	ConversationsRename(context.Context, *ConversationsRenameRequest) (*structpb.Struct, error)
	// conversations.setTopic -- set the topic on a channel.
	ConversationsSetTopic(context.Context, *ConversationsSetTopicRequest) (*structpb.Struct, error)
	// conversations.setPurpose -- set the purpose on a channel.
	ConversationsSetPurpose(context.Context, *ConversationsSetPurposeRequest) (*structpb.Struct, error)
	// conversations.members -- list members of a channel.
	ConversationsMembers(context.Context, *ConversationsMembersRequest) (*structpb.Struct, error)
	// conversations.open -- open or resume a DM/MPIM.
	ConversationsOpen(context.Context, *ConversationsOpenRequest) (*structpb.Struct, error)
	// users.list -- list all users in the workspace.
	UsersList(context.Context, *UsersListRequest) (*structpb.Struct, error)
	// users.info -- get profile/metadata for a single user.
	UsersInfo(context.Context, *UsersInfoRequest) (*structpb.Struct, error)
	// users.lookupByEmail -- find a user by email address.
	UsersLookupByEmail(context.Context, *UsersLookupByEmailRequest) (*structpb.Struct, error)
	// users.profile.get -- get the profile object for a user.
	UsersProfileGet(context.Context, *UsersProfileGetRequest) (*structpb.Struct, error)
	// users.getPresence -- get the presence (active/away) of a user.
	UsersGetPresence(context.Context, *UsersGetPresenceRequest) (*structpb.Struct, error)
	// reactions.add -- add an emoji reaction to a message.
	ReactionsAdd(context.Context, *ReactionsAddRequest) (*structpb.Struct, error)
	// reactions.remove -- remove an emoji reaction from a message.
	ReactionsRemove(context.Context, *ReactionsRemoveRequest) (*structpb.Struct, error)
	// reactions.get -- list reactions on a specific message.
	ReactionsGet(context.Context, *ReactionsGetRequest) (*structpb.Struct, error)
	// pins.add -- pin a message in a channel.
	PinsAdd(context.Context, *PinsAddRequest) (*structpb.Struct, error)
	// pins.remove -- unpin a message.
	PinsRemove(context.Context, *PinsRemoveRequest) (*structpb.Struct, error)
	// pins.list -- list pinned items in a channel.
	PinsList(context.Context, *PinsListRequest) (*structpb.Struct, error)
	// search.messages -- search messages across the workspace (user token only).
	SearchMessages(context.Context, *SearchMessagesRequest) (*structpb.Struct, error)
	// search.files -- search files across the workspace (user token only).
	SearchFiles(context.Context, *SearchFilesRequest) (*structpb.Struct, error)
	// files.list -- list files in the workspace.
	FilesList(context.Context, *FilesListRequest) (*structpb.Struct, error)
	// files.info -- get info for a file.
	FilesInfo(context.Context, *FilesInfoRequest) (*structpb.Struct, error)
	// files.delete -- delete a file.
	FilesDelete(context.Context, *FilesDeleteRequest) (*structpb.Struct, error)
	// bookmarks.list -- list bookmarks for a channel.
	BookmarksList(context.Context, *BookmarksListRequest) (*structpb.Struct, error)
	// bookmarks.add -- add a bookmark to a channel.
	BookmarksAdd(context.Context, *BookmarksAddRequest) (*structpb.Struct, error)
	// bookmarks.remove -- remove a bookmark from a channel.
	BookmarksRemove(context.Context, *BookmarksRemoveRequest) (*structpb.Struct, error)
	// team.info -- get info about the connected workspace.
	TeamInfo(context.Context, *TeamInfoRequest) (*structpb.Struct, error)
	// emoji.list -- list custom emoji in the workspace.
	EmojiList(context.Context, *EmojiListRequest) (*structpb.Struct, error)
	// views.open -- open a modal view in response to a trigger.
	ViewsOpen(context.Context, *ViewsOpenRequest) (*structpb.Struct, error)
	// views.publish -- publish a Home tab view for a user.
	ViewsPublish(context.Context, *ViewsPublishRequest) (*structpb.Struct, error)
}

